 3→namespace App\Http\Controllers;
 4→
 5→use App\Models\SanitaryCampaign;
 6→use Inertia\Inertia;
 7→use Inertia\Response;
 8→
 9→class SanitaryCampaignController extends Controller
10→{
11→    public function index(): Response
12→    {
13→        $exploitation = auth()->user()->exploitation;
14→
15→        $campaigns = SanitaryCampaign::query()
16→            ->where('exploitation_id', $exploitation->id)
17→            ->with('campaignAnimals.animal')
18→            ->get();
19→
20→        $immobilizedAnimals = $campaigns
21→            ->flatMap(fn (SanitaryCampaign $c) => $c->campaignAnimals
22→                ->where('status', 'immobilized')
23→                ->map(fn ($ca) => $ca->setAttribute('campaign_name', $c->name)->setAttribute('campaign_id', $c->id)))
24→            ->groupBy(fn ($ca) => $ca->animal->species.'|'.($ca->restriction_type ?? 'blocked'));
25→
26→        return Inertia::render('normativa/campanas/index', [
27→            'campaigns' => $campaigns,
28→            'immobilizedAnimals' => $immobilizedAnimals,
29→        ]);
30→    }
31→
32→    public function show(SanitaryCampaign $sanitaryCampaign): Response
33→    {
34→        $sanitaryCampaign->load(['campaignAnimals.animal', 'exploitation']);
35→
36→        $animals = $sanitaryCampaign->campaignAnimals->groupBy('status');
37→
38→        return Inertia::render('normativa/campanas/show', [
39→            'campaign' => $sanitaryCampaign,
40→            'animals' => [
41→                'pending' => $animals->get('pending', collect())->values(),
42→                'sampled' => $animals->get('sampled', collect())->values(),
43→                'immobilized' => $animals->get('immobilized', collect())->values(),
44→            ],
45→        ]);
46→    }
47→}
